import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十六卦 大畜 山天大畜 艮上乾下","description":"周易 - 第二十六卦 大畜 山天大畜 艮上乾下","frontmatter":{"title":"第二十六卦 大畜 山天大畜 艮上乾下","description":"周易 - 第二十六卦 大畜 山天大畜 艮上乾下"},"headers":[],"relativePath":"classics/zhouyi/027.md","filePath":"classics/zhouyi/027.md"}'),l={name:"classics/zhouyi/027.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="大畜" tabindex="-1">大畜 <a class="header-anchor" href="#大畜" aria-label="Permalink to “大畜”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利貞，不家食吉，利涉大川。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>大畜，剛健篤實輝光，日新其德，剛上而尚賢。能止健，大正也。不家食吉，養賢也。利涉大川，應乎天也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天在山中，大畜；君子以多識前言往行，以畜其德。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>有厲利已。象曰：有 厲利已，不犯災也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>輿說輻。象曰：輿說輻，中無尤也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>良馬逐，利艱貞。曰閒輿衛，利有攸往。象曰：利有攸往，上合志也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>童豕之牿，元吉。象曰：六四元吉，有喜也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>豶豕之牙，吉。象曰：六五之吉，有慶也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>何天之衢，亨。象曰：何天之衢，道大行也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
